mapper.select:
SELECT DISTINCT A.* FROM coach A 
LEFT JOIN coach_provide B ON A.coach_idx = B.coach_idx 
LEFT JOIN coach_region C ON A.coach_idx = C.coach_idx
LEFT JOIN USER_HASHTAG UH ON A.user_idx = UH.user_idx
LEFT JOIN HASHTAG H ON UH.hashtag_idx = H.hashtag_idx

    (A.nickname LIKE '%' || #{keyword} || '%' OR H.TAGS LIKE '%' || #{keyword} || '%')

        AND B.minor_field_idx = #{minorField}


        AND C.major_region_idx = #{majorRegion}


        AND C.minor_region_idx = #{minorRegion}
